B.PM=new A.e0("traffic","Traffic light","Traffic light","Basics","Beginner","Sequence three LEDs with timing.","Three LEDs and a button","V2 \xb7 Uno \xb7 ESP32",'// Traffic light\n// Red, amber and green LEDs on pins 4, 5 and 6.\n// A push button between pin 2 and GND asks the light to change.\n#define BUTTON_PIN 2\n\nconst int RED = 4;\nconst int AMBER = 5;\nconst int GREEN = 6;\n\nvoid setup() {\n  Serial.begin(115200);\n  pinMode(RED, OUTPUT);\n  pinMode(AMBER, OUTPUT);\n  pinMode(GREEN, OUTPUT);\n  pinMode(BUTTON_PIN, INPUT_PULLUP);\n}\n\nvoid show(int pin, String name) {\n  digitalWrite(RED, pin == RED);\n  digitalWrite(AMBER, pin == AMBER);\n  digitalWrite(GREEN, pin == GREEN);\n  Serial.println(name);\n}\n\nvoid loop() {\n  show(GREEN, "green");\n  // Stay green for 5 seconds, or until the button is pressed\n  unsigned long start = millis();\n  while (digitalRead(BUTTON_PIN) == HIGH && millis() - start < 5000) {\n    delay(20);\n  }\n  show(AMBER, "amber");\n  delay(1000);\n  show(RED, "red");\n  delay(4000);\n}\n',null,B.Xz,"TrafficLight",B.Xu,null)
B.PI=new A.e0("ultrasonic","Ultrasonic distance","Ultrasonic distance","Sensors","Intermediate","Measure distance and print it.","Sonar readings to serial","RoboCore V2",u.X,null,null,"UltrasonicDistance",null,null)
B.PP=new A.e0("tones","Buzzer tones","Buzzer tones","Sound & light","Beginner","Play notes with tone() and noTone().","A rising scale","V2 \xb7 Uno \xb7 ESP32","// Buzzer tones\n// Plays a rising scale on the buzzer (pin 8).\nconst int BUZZER = 8;\n\nvoid setup() {\n  pinMode(BUZZER, OUTPUT);\n}\n\nvoid loop() {\n  tone(BUZZER, 262, 300);   // C4\n  delay(350);\n  tone(BUZZER, 330, 300);   // E4\n  delay(350);\n  tone(BUZZER, 392, 300);   // G4\n  delay(350);\n  tone(BUZZER, 523, 600);   // C5\n  delay(650);\n  noTone(BUZZER);\n  delay(1000);\n}\n",null,null,"BuzzerTones",null,null)
B.PO=new A.e0("motors","Motor control","Motor control","Robotics","Intermediate","Drive, reverse and turn.","Both motor ports","RoboCore V2",'// Motor control\n// Drives forward, reverses, then turns on the spot.\n#include <RoboCoreMotors.h>\n\nRoboCoreMotors motors;\n\nvoid setup() {\n  Serial.begin(115200);\n  motors.begin();\n}\n\nvoid loop() {\n  Serial.println("forward");\n  motors.drive(60, 60);\n  delay(1500);\n  Serial.println("reverse");\n  motors.drive(-60, -60);\n  delay(1500);\n  Serial.println("turn");\n  motors.drive(-50, 50);\n  delay(800);\n  motors.stop();\n  delay(1000);\n}\n',null,null,"MotorControl",null,null)
B.PS=new A.e0("imu","Sensors to serial","Sensors to serial","Sensors","Beginner","Print temperature and IMU readings.","IMU and temperature","RoboCore V2",'// Sensors to serial\n// Prints the board temperature and tilt twice a second.\n#include <RoboCoreSensors.h>\n\nIMU imu;\n\nvoid setup() {\n  Serial.begin(115200);\n  imu.begin();\n}\n\nvoid loop() {\n  Serial.print("temp_c=");\n  Serial.print(imu.temperature(), 1);\n  Serial.print("  tilt_deg=");\n  Serial.println(imu.tiltDeg(), 1);\n  delay(500);\n}\n',null,null,"SensorsToSerial",null,null)
B.PV=new A.e0("obstacle","Obstacle avoider","Obstacle avoider","Robotics","Advanced","Steer around walls with sonar.","Sonar + motors","RoboCore V2",'// Obstacle avoider\n// Drives forward and turns left when something is closer than 20 cm.\n#include <RoboCoreMotors.h>\n#include <RoboCoreSensors.h>\n\nRoboCoreMotors motors;\nSonar sonar;\n\nconst int LIMIT_CM = 20;\n\nvoid setup() {\n  Serial.begin(115200);\n  motors.begin();\n  sonar.begin();\n}\n\nvoid loop() {\n  float cm = sonar.distanceCm();\n  Serial.print("distance_cm=");\n  Serial.println(cm, 1);\n\n  if (cm < LIMIT_CM) {\n    Serial.println("obstacle \u2014 turning left");\n    motors.drive(-50, 50);\n    delay(400);\n  } else {\n    motors.drive(60, 60);\n  }\n  delay(250);\n}\n',null,null,"ObstacleAvoider",null,null)
B.PQ=new A.e0("robot_avoider","Robot obstacle avoider","Robot avoider","Robotics","Beginner","Drives forward, and beeps and turns right at anything closer than 20 cm. USER stops it.","The robot blocks","RoboCore V2","// Robot avoider\n// Made with blocks in RoboCore IDE.\n\n#include <RoboCore.h>\n\nRoboCoreMotors motors;\nSonar sonar;\nIMU imu;\nRoboCoreDrive robot(motors, imu);\n\nvoid setup() {\n  motors.begin();\n  sonar.begin();\n  robot.setSpeed(50);\n}\n\nvoid loop() {\n  if (RoboCore::userJustPressed()) {\n    robot.stop();\n    RoboCore::stopProgram();\n  }\n  if (sonar.distanceCm() < 20) {\n    robot.stop();\n    RoboCore::beep(523, 200);  // C5\n    robot.turn(90);\n  } else {\n    robot.start(FORWARD);\n  }\n}\n","RobotAvoider",null,null,null,'{"blocks":{"languageVersion":0,"blocks":[{"type":"rc_on_start","x":24,"y":24,"inputs":{"DO":{"block":{"type":"rc_move_speed","inputs":{"PCT":{"shadow":{"type":"math_number","fields":{"NUM":50}}}}}}}},{"type":"rc_forever","x":24,"y":168,"inputs":{"DO":{"block":{"type":"controls_if","extraState":{"hasElse":true},"inputs":{"IF0":{"block":{"type":"rc_closer","inputs":{"CM":{"shadow":{"type":"math_number","fields":{"NUM":20}}}}}},"DO0":{"block":{"type":"rc_stop_moving","next":{"block":{"type":"rc_beep","fields":{"NOTE":"C5"},"inputs":{"SECS":{"shadow":{"type":"math_number","fields":{"NUM":0.2}}}},"next":{"block":{"type":"rc_turn","fields":{"DIR":"right"},"inputs":{"DEG":{"shadow":{"type":"math_number","fields":{"NUM":90}}}}}}}}}},"ELSE":{"block":{"type":"rc_start_moving","fields":{"DIR":"forward"}}}}}}}},{"type":"rc_when_user","x":460,"y":24,"inputs":{"DO":{"block":{"type":"rc_stop_moving","next":{"block":{"type":"rc_stop_program"}}}}}}]}}')
